CREATE TABLE t (id Uint64 NOT NULL, ts Timestamp, PRIMARY KEY (id)) WITH (AUTO_PARTITIONING_BY_SIZE = DISABLED, AUTO_PARTITIONING_BY_LOAD = ENABLED, AUTO_PARTITIONING_MIN_PARTITIONS_COUNT = 2, AUTO_PARTITIONING_MAX_PARTITIONS_COUNT = 8, READ_REPLICAS_SETTINGS = "ANY_AZ:2", KEY_BLOOM_FILTER = ENABLED, UNIFORM_PARTITIONS = 4, TTL = Interval("P7D") ON ts);